package  objeto.orientacao.exercise.domain;import java.util.Scanner;public class Funcionario {    private String nome;    private int idade;    private double[] salario;    private double media;    public void setNome(String nome) {        this.nome = nome;    }    public void setSalario(double[] salario) {        this.salario = salario;    }    public void setIdade(int idade) {        this.idade = idade;    }    public void setMedia(double media) {        for ( double s : this.salario ){            double sal = 0;            sal  += s;            media = sal / this.salario.length;            this.media = media;        }    }    public void imprime(){        System.out.println(this.nome);        System.out.println(this.idade);        System.out.println(this.media);        System.out.println(this.salario);    }}